/* @lc app=leetcode id=3680 lang=kotlin */ class Solution { fun generateSchedule(n: Int): Array<IntArray> = if (n < 5) arrayOf() else BooleanArray(n * n).let { used -> IntArray(n) { 2 * (n - 1) }.let { rem -> generateSequence(intArrayOf(-1, -1)) { prev -> (0 until n * n).filter { x -> x / n != x % n && !used[x] && x / n != prev[0] && x / n != prev[1] && x % n != prev[0] && x % n != prev[1] }.maxByOrNull { rem[it / n] + rem[it % n] }?.let { x -> used.set(x, true).also { rem[x / n]-- }.also { rem[x % n]-- }.let { intArrayOf(x / n, x % n) } } }.drop(1).toList().toTypedArray() } } }